func maxRateDelta(deltas []float64) float64 {
        var best float64
        for i, d := range deltas {
                if i == 0 {
                        best = d
                        continue
                }
                if math.Abs(d) > math.Abs(best) || (math.Abs(d) == math.Abs(best) && d > best) {
                        best = d
                }
        }
        return best
}

func minRateDelta(deltas []float64) float64 {
        var best float64
        for i, d := range deltas {
                if i == 0 {
                        best = d
                        continue
                }
                if math.Abs(d) < math.Abs(best) || (math.Abs(d) == math.Abs(best) && d > best) {
                        best = d
                }
        }
        return best
}

func populationStdDev(values []float64) float64 {
        if len(values) == 0 {
                return 0
        }
        mean := meanOfValues(values)
        var sumSqDiff float64
        for _, v := range values {
                diff := v - mean
                sumSqDiff += diff * diff
        }
        return math.Sqrt(sumSqDiff / float64(len(values)))
}

